-- MAIL-DOC-01: one deliberately chosen, already finalized document may travel
-- with a mail. Additive only: one new tenant-bound table, two widened closed
-- vocabularies, no change to any existing row.
--
-- The row references the frozen artefact of the document by its content hash.
-- The bytes stay in the content-addressed store and are read again for every
-- attempt; the database never holds a copy of a PDF and a mail can never carry
-- a freshly rendered document. `filename` is generated by the server from the
-- document number, so no operator input ever becomes a file name or path.
CREATE TABLE mail_attachments (
 tenant_id uuid NOT NULL REFERENCES tenants(id),
 message_id uuid NOT NULL,
 document_id uuid NOT NULL,
 -- The very artefact the PDF route serves for this final document.
 pdf_hash text NOT NULL CHECK(pdf_hash ~ '^[a-f0-9]{64}$'),
 filename text NOT NULL CHECK(filename ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,120}\.pdf$'),
 media_type text NOT NULL DEFAULT 'application/pdf' CHECK(media_type='application/pdf'),
 size_bytes bigint NOT NULL CHECK(size_bytes BETWEEN 1 AND 10485760),
 created_at timestamptz NOT NULL DEFAULT now(),
 -- A document travels at most once with one message; several different
 -- documents per message stay possible without dropping a constraint later.
 PRIMARY KEY(tenant_id,message_id,document_id),
 FOREIGN KEY(tenant_id,message_id) REFERENCES mail_messages(tenant_id,id) ON DELETE CASCADE,
 FOREIGN KEY(tenant_id,document_id) REFERENCES documents(tenant_id,id) ON DELETE RESTRICT
);
-- The one hard rule that cannot live in a single row: an attachment only ever
-- points at a finalized document. A withdrawn or draft row is refused here, not
-- only by the repository - and because the hash and the bytes are frozen, a
-- later withdrawal never changes the artefact that was referenced.
CREATE FUNCTION mail_attachments_require_final() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM documents d
     WHERE d.tenant_id=NEW.tenant_id AND d.id=NEW.document_id AND d.state='final'
  ) THEN
    RAISE EXCEPTION 'mail attachment document is not final';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER mail_attachments_final
  BEFORE INSERT OR UPDATE ON mail_attachments
  FOR EACH ROW EXECUTE FUNCTION mail_attachments_require_final();

-- Two closed vocabularies are widened in the established 0052/0064/0066/0067/
-- 0068 pattern; every earlier action and code keeps its meaning.
ALTER TABLE audit_events DROP CONSTRAINT audit_events_action_check;
ALTER TABLE audit_events ADD CONSTRAINT audit_events_action_check CHECK(action IN (
 'login.succeeded','login.denied','login.failed','logout','master_data.created','master_data.updated',
 'resource.created','resource.updated','product.created','product.updated','product.deleted','contact.created','contact.updated',
 'location.created','location.updated','event.created','event.updated','reservation.created','reservation.updated','reservation.expired',
 'import.created','import.updated','import.reviewed','password.changed','password.change_denied','password.reset',
 'feed.created','feed.rotated','feed.revoked',
 'document_template.created','document_template.updated',
 'document_number.updated','document_layout.updated',
 'document.created','document.updated','document.finalized',
 'document.sent','document.accepted','document.withdrawn','document.acceptance_corrected',
 'file.uploaded','file.archived','payment.recorded','file.event_linked','file.event_unlinked',
 'event.removed','event.restored',
 'mail.message_created','mail.send_scheduled',
 'mail.sent','mail.send_retry',
 'mail.document_send_scheduled'
));
-- A referenced artefact that cannot be read is its own operator task (storage
-- or retention), not a provider refusal; the closed code set says so.
ALTER TABLE mail_outbox DROP CONSTRAINT mail_outbox_last_error_code_check;
ALTER TABLE mail_outbox ADD CONSTRAINT mail_outbox_last_error_code_check
  CHECK(last_error_code IS NULL OR last_error_code IN
    ('provider_missing','provider_timeout','provider_rejected','provider_uncertain','internal',
     'provider_auth_failed','provider_recipient_rejected','encryption_unavailable',
     'provider_tls_required','attachment_unavailable'));
